INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '236c97cd-02fe-5900-b54f-61a0b467df1b', '5a7a30be-20cd-5963-a9e2-f3e94225f67c',
  '26. (1.0) Một record của bệnh nhân gồm có $N$ trường thông tin. Giả sử rằng chúng ta có đủ kiến thức để chẩn đoán bệnh dựa vào các thuộc tính này. Hãy chọn dựa một cấu trúc dữ liệu phù hợp để đặc tả luật chẩn đoán.

